window.__BUNDLE__={"generatedAt":"2026-11-09T01:23:10.806890+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-11-02","archiveCutoff":"2021-11-10","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":252,"arxiv":1260,"total":1512},"freshness":{"latestPaperDate":"2026-11-06","latestPublishedDate":"2026-11-06","latestBatchCount":264,"newInLast24h":0,"newInLast48h":0},"historyTotal":30884,"topicCounts":{"Multi-Agent":3225,"Evaluation":16970,"Planning":2247,"Memory":604,"Code Agent":1245,"Interpretability":1025,"Agentic RAG":1588,"Agentic Search":2138,"RL for LLM":1614,"Reasoning":8184,"Hallucination":1325,"Post-Training":3392,"Alignment":3976,"World Model":617,"Tool Use":1487,"Agent Safety":2791,"Computer Use":406,"Reflection":1097,"VLM Training":2442,"LLM Training":3976,"Fine-tuning":4811,"Multimodal Agent":178,"Agent Framework":983,"Error Attribution":193,"Data Engine":616},"count":36,"recentTotal":1916,"archiveCount":0,"archiveTotal":28968,"sources":{"hf":45,"arxiv":1871,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"url":"https://arxiv.org/abs/2611.08449","pdf":"https://arxiv.org/pdf/2611.08449.pdf","arxiv":"https://arxiv.org/abs/2611.08449","date":"2026-11-06","source":"hf","announceDate":"2026-11-06","topics":["VLM Training","Planning"],"authors":["Yu-Cheng Chou","Shihao Wang","Jin Huang","Chi-Pin Huang","Chiao-An Yang","Xianzhe Fan","Jing Wang","Zhiqi Li","Yuanguo Kuang","Ruijie Zheng","Johan Bjorck","Sifei Liu","Hang Su","Abhishek Badki","Lei Zhang","Alan Yuille","Linxi \"Jim'' Fan","Jan Kautz","Zhiding Yu"],"tags":["VLM Training","Planning"],"upvotes":106,"submittedDate":"2026-11-05","id":"arxiv:2611.08449","title":"VFlash: Fast, Accurate Visual Planning via Flash Primitive Decoding","hfUrl":"https://huggingface.co/papers/2611.08449","abstract":"Models for physical AI tasks, such as robotics and autonomous driving, need not reason solely in language. They can use visual plans--points, bounding boxes, and trajectories--to represent spatial goals and anticipate motion. However, autoregressive vision-language models generate these plans one coordinate token at a time, making richer predictions increasingly costly. We introduce VFlash, a method for fast, accurate visual planning through Flash Primitive Decoding. VFlash exploits the known structure of visual primitives to predict their coordinates jointly, using a lightweight drafter that generates an entire primitive in one forward pass. The layout adapts to the primitive's type, dimensionality, and length, supporting compact boxes and long, variable-length trajectories. Crucially, spatial accuracy need not require reproducing an autoregressive model's exact token sequence. VFlash t"},{"url":"https://arxiv.org/abs/2611.08373","pdf":"https://arxiv.org/pdf/2611.08373.pdf","arxiv":"https://arxiv.org/abs/2611.08373","date":"2026-11-06","source":"hf","topics":["Post-Training","LLM Training","VLM Training","Alignment"],"authors":["Fuhao Li","Wenxuan Song","Qizhou Huang","Ziyang Zhou","Jingbo Wang","Junwu E","Pengwei Wang","Yan Wang","Shunbo Zhou","Haoang Li"],"tags":["Post-Training","LLM Training","VLM Training","Alignment"],"upvotes":92,"id":"arxiv:2611.08373","title":"SLA: Scaling Spatial-Language-Action Model via Continual Pre-training","hfUrl":"https://huggingface.co/papers/2611.08373","abstract":"Reliable robotic manipulation requires both semantic understanding and precise control in three-dimensional space. However, vision-language-action (VLA) foundations largely inherit visual representations from 2D vision-language pre-training, while spatial supervision is often introduced only during task-specific adaptation. Developing spatial understanding as a transferable foundation-model capability therefore calls for learning from broader robot experience. We present SLA, a Spatial-Language-Action Model that scales implicit spatial alignment to continual pre-training and maintains it during downstream post-training. Initialized from a pretrained pi05 policy, SLA jointly optimizes action prediction and alignment between intermediate visual embeddings and spatial representations from a frozen 3D perception model. We curate and unify heterogeneous robot datasets to support spatial learn"},{"url":"https://arxiv.org/abs/2611.07392","pdf":"https://arxiv.org/pdf/2611.07392.pdf","arxiv":"https://arxiv.org/abs/2611.07392","date":"2026-11-06","source":"hf","announceDate":"2026-11-06","topics":["Evaluation","Data Engine"],"authors":["Canmiao Fu","Chen Li","Guohui Zhang","Hao Lu","Hongyang Wei","Huadong Wu","Huaisong Zhang","Hubery Yin","Liyuan Cui","Qixin Yan","Tong Shao","Xiaoqiang Zhou","Xinhang Leng","Ying Zhang","Zhenhai Liu","Zhipeng Huang"],"tags":["Evaluation","Data Engine"],"upvotes":44,"submittedDate":"2026-11-05","id":"arxiv:2611.07392","title":"WeLM-Image: A Unified Image Generation Model towards Visual Intelligence","hfUrl":"https://huggingface.co/papers/2611.07392","abstract":"We present \\textbf{WeLM-Image}, a unified image foundation model that integrates multimodal understanding into text-to-image generation, instruction-guided editing, and multi-reference synthesis. Designed for single-GPU deployment in WeChat's large-scale consumer applications, the model processes text, reference images, and target latents as one interleaved sequence. A Mixture-of-Transformers (MoT) backbone combines shared attention with independent understanding and generation parameters to limit optimization interference. Equipping each path with Mixture-of-Experts (MoE) modules provides sparse capacity, with 31.7B stored parameters and approximately 5.4B generation parameters activated per target latent token. A generation-oriented data engine combines a knowledge-grounded visual vocabulary with large-scale visual clustering to balance semantic coverage and editing tasks, while traini"},{"url":"https://arxiv.org/abs/2611.07854","pdf":"https://arxiv.org/pdf/2611.07854.pdf","arxiv":"https://arxiv.org/abs/2611.07854","date":"2026-11-06","source":"hf","announceDate":"2026-11-06","topics":["LLM Training","Reasoning","Fine-tuning"],"authors":["Nischay Dhankhar","Alisher Amantay","Zhanibek Datbayev","Darkhan Akhmetov","Yash Shah","Nurmukhamed Ubaidullayev","Raman Saparkhan","Dos Baha","Abulhair Saparov"],"tags":["LLM Training","Reasoning","Fine-tuning"],"upvotes":22,"submittedDate":"2026-11-05","id":"arxiv:2611.07854","title":"Towards Foundation Decision Models: Drex","hfUrl":"https://huggingface.co/papers/2611.07854","abstract":"Autoregressive approaches with large language models, such as long chain-of-thought reasoning, have become the default for new AI applications because they reach higher accuracy on a wide range of tasks. In production, however, they give inconsistent answers, require parsing of outputs, and add cost and latency. Decision models address this: given a question and a set of options supplied by the user, they return a probability distribution over the options without autoregressive decoding. We present Drex, a family of four open decision models with 8B (DLM), 9B (v1.5), 35B with 3B active (v2.0), and 27B (Max) parameters. Each request consists of a state (a document, record, or agent context, optionally with images) and questions about it, each asking for a choice among options, a yes/no judgment, or a score on an ordered scale. Training combines supervised fine-tuning with reinforcement le"},{"url":"https://arxiv.org/abs/2611.06982","pdf":"https://arxiv.org/pdf/2611.06982.pdf","arxiv":"https://arxiv.org/abs/2611.06982","date":"2026-11-06","source":"hf","topics":["Evaluation"],"authors":["Yutong Bian","Yanglin Zhang","Yuxiang Wang","Luoyuan Zhang","Rongshen He","Zihao Wang","Junwen Qiu","Jiaqi Li","Zhizheng Wu"],"tags":["Evaluation"],"upvotes":8,"id":"arxiv:2611.06982","title":"Decode Before You Hear: Speculative Listening for Chunk-Interleaved Full-Duplex Speech Language Models","hfUrl":"https://huggingface.co/papers/2611.06982","abstract":"Chunk-interleaved full-duplex speech language models listen and speak in fixed time chunks, and each chunk must be processed before the next one arrives. Their workload is asymmetric across chunks: listen chunks leave compute idle while awaiting audio, and speak and tool-call chunks require serial generation, which delays responses and tool calls. Using the idle compute for the next chunk requires decoding it before its audio arrives, under an assumed input. Taking silence as the assumed input and comparing the output with the output under real audio on four models, we observe two properties. First, the next audio chunk does not change the output in 95.3% of chunks. Second, 88% of changes begin at the first output token. Building on these properties, we propose Speculative Listening, a training-free, lossless framework for input-time self-speculative decoding. During idle time, the model"},{"url":"https://arxiv.org/abs/2611.08369","pdf":"https://arxiv.org/pdf/2611.08369.pdf","arxiv":"https://arxiv.org/abs/2611.08369","date":"2026-11-06","source":"hf","announceDate":"2026-11-06","topics":["Reasoning","Planning","Evaluation"],"authors":["Pengkai Wang","Wei-Wei Zhang","Yan Li","Min Tang","Zhitian Hou","Zeyu Liu","Guanghao Zhu","Yuanyi Wang","Yanggan Gu","Wenjun Wang","Minheng Ni","Congkai Xie","Zhijie Sang","Jianmin Wu","Ying Sun","Hongxia Yang"],"tags":["Reasoning","Planning","Evaluation"],"upvotes":3,"submittedDate":"2026-11-05","id":"arxiv:2611.08369","title":"NPCBench: A Clinical Apprenticeship Benchmark for Multimodal Care-Pathway Reasoning in Nasopharyngeal Carcinoma","hfUrl":"https://huggingface.co/papers/2611.08369","abstract":"Current medical benchmarks typically break down clinical competence into isolated factual questions, single-image tasks, or static case vignettes. These tests score individual answers, but reveal less about whether a model can integrate subspecialty knowledge with multimodal evidence and track a patient's condition throughout a course of care. To close this gap, we introduce NPCBench, a clinical apprenticeship benchmark for nasopharyngeal carcinoma (NPC). NPCBench mirrors specialist training, from guideline and foundational knowledge to case planning, longitudinal review, CarePath integration, and open-ended consultation. It contains 4,777 component and consultation items and a 100-patient CarePath cohort with 417 scored diagnostic and care tasks. The episode-level evaluation tests whether diagnostic and care answers are jointly correct within a care pathway. By linking stepwise tasks to"},{"url":"https://arxiv.org/abs/2611.08237","pdf":"https://arxiv.org/pdf/2611.08237.pdf","arxiv":"https://arxiv.org/abs/2611.08237","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Evaluation"],"authors":["Xiaojun Wu","Cehao Yang","Xuhui Jiang","Chengjin Xu","Jia Li","Jian Guo"],"tags":["Evaluation"],"upvotes":11,"submittedDate":"2026-11-05","id":"arxiv:2611.08237","title":"Terminal-style Mathematical Modeling Bench: The First Agentic and Verifiable Benchmark for Mathematical Modeling","hfUrl":"https://huggingface.co/papers/2611.08237","abstract":"Mathematical modeling turns an open-ended real-world problem into assumptions, a model, a solution, and a defended recommendation, and its answers matter only if they are both close to a credible reference and physically feasible; existing benchmarks either score solver fragments or grade reports with an LLM judge, leaving those numbers unchecked. We introduce TB-MathModel (the Terminal-style Mathematical Modeling Bench), the first benchmark to make complete contest-style modeling problems agentic, verifiable, and terminal at once, over 18 real CUMCM and MCM problems (2023--2025). Each task ships the verbatim statement, official attachments, and figures in a containerized terminal; the agent returns one JSON artifact, scored on the numeric core of the final question against a reproduction of the Outstanding-award paper. Two design choices distinguish it: direction-aware, one-sided scorin"},{"url":"https://arxiv.org/abs/2611.08483","pdf":"https://arxiv.org/pdf/2611.08483.pdf","arxiv":"https://arxiv.org/abs/2611.08483","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Reasoning"],"authors":["Qile Jiang","George Em Karniadakis"],"tags":["Reasoning"],"upvotes":9,"submittedDate":"2026-11-05","id":"arxiv:2611.08483","title":"SwarmEvolve: Latent Agent Swarms for Evolutionary Discovery and Optimization","hfUrl":"https://huggingface.co/papers/2611.08483","abstract":"LLM-guided evolutionary search uses AI agents to improve programs for mathematical and computational problems by iteratively refining solutions and combining high-scoring methods. However, the process is often slow because the LLM generates a long textual chain of thought for each round and must repeat this generation many times to maintain population diversity. We present SwarmEvolve, a framework in which hundreds of low-cost agents per round work in swarms, reason in latent space without decoding to text, and share information by passing KV caches. Each swarm studies the problem from a different angle. A novelty filter keeps the most distinct agent ideas by directly measuring the distances between the agents' hidden state vectors. Crossover of ideas happens naturally in latent space, as a summarizer agent receives the combined KV caches of all swarm members. On 21 problems in mathemati"},{"url":"https://arxiv.org/abs/2611.08219","pdf":"https://arxiv.org/pdf/2611.08219.pdf","arxiv":"https://arxiv.org/abs/2611.08219","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM","Data Engine"],"authors":["Teng Pan","Zixuan Wang","Yuchen Yan","Qifei Wu","Yao Chen","Yingqi Qu","Ruiqing Zhang","Yongliang Shen"],"tags":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08219","title":"Agent-R$^2$: Scaling Agents for Realistic Productivity Work via Real-Source Data Synthesis","abstract":"Large language models have made rapid progress in agentic reasoning and tool use, raising expectations for agents that can take over realistic productivity work from humans. However, current agents still struggle to finish such tasks, where success requires following long-horizon professional workflows, understanding heterogeneous file contexts, and producing usable deliverables under fine-grained requirements. A key bottleneck is the lack of scalable post-training data that reflects real work intent, authentic file environments, and deliverable-level evaluation. To close this gap, we introduce Agent-R$^2$, a $\\textbf{r}$eal-source data synthesis framework that scales training data for $\\textbf{r}$ealistic productivity work. Instead of relying on manually specified workflows or LLM-generated files, Agent-R$^2$ grounds synthesis throughout the pipeline in real occupational seeds, corpus-d"},{"url":"https://arxiv.org/abs/2611.07216","pdf":"https://arxiv.org/pdf/2611.07216.pdf","arxiv":"https://arxiv.org/abs/2611.07216","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"authors":["Hong kyu Lee","Kai Shu","Li Xiong"],"tags":["LLM Training","VLM Training","Reasoning","Evaluation","Alignment"],"upvotes":0,"submittedDate":"2026-11-04","id":"arxiv:2611.07216","title":"Compositional Unalignment: Auditing Safety in Large Vision-Language Models","abstract":"Large vision-language models (LVLMs) are vulnerable to compositional harm: an image and a prompt that are benign in isolation become harmful through the model's cross-modal reasoning. Recent alignment methods report strong scores on compositional safety benchmarks, but an LLM judge only measures observed behavior and cannot reveal how robustly safety is integrated into the model. We argue that un-alignment provides a complementary audit of alignment robustness. We first show that minimal supervised fine-tuning reaches an LLM-judge score comparable to a multi-stage reinforcement-learning pipeline, so similar benchmark scores cannot establish robustness by themselves. We then show that recognition and refusal of compositional harm are decoupled: nine standard direction-finding methods detect compositional harm with up to AUC=0.99, yet ablating the recovered directions either leaves refusal"},{"url":"https://arxiv.org/abs/2611.07825","pdf":"https://arxiv.org/pdf/2611.07825.pdf","arxiv":"https://arxiv.org/abs/2611.07825","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"authors":["Jisen Lei","Huizhi Liang"],"tags":["LLM Training","Reasoning","Planning","Evaluation","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07825","title":"Generate-then-Rank: Learning Symbolic Goal Interpretation for Embodied Agents","abstract":"Goal interpretation is to translate a natural language instruction into a formal symbolic goal that a planner can execute. It is critical for embodied agents because any error here propagates to every downstream planning and action step. Doing it well requires both generating suitable candidates and reliably selecting among them. We present a two-stage generate-then-rank approach to Goal Interpretation in the Embodied Agent Interface (EAI). First, supervised fine-tuning adapts a Large Language Model (LLM) to EAI's output convention. Second, Candidate-Output Ranking from Errors (CORE) learns preferences over complete outputs from the model's own generated alternatives. We conducted experiments on the household scenes of the Embodied Agent Interface Benchmark. Multiple open source LLMs including DeepSeek-V3 chat, DeepSeek-Reasoner, and Qwen2.5-7B and Qwen2.5-72B were evaluated. The propose"},{"url":"https://arxiv.org/abs/2611.07689","pdf":"https://arxiv.org/pdf/2611.07689.pdf","arxiv":"https://arxiv.org/abs/2611.07689","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Agent Safety","Error Attribution","Reasoning","Hallucination","Evaluation"],"authors":["Yizhen Jiang","Haowei Guo","Tianyi Bai","Zengjie Hu","Lu Ma","Zhengyang Zhao","Haoze Sun","Peng Pei","Wentao Zhang"],"tags":["Agent Safety","Error Attribution","Reasoning","Hallucination","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07689","title":"MCPHallu: Benchmarking Reasoning, Execution, and Memory Hallucinations in MCP Agents","abstract":"Large language model agents are increasingly deployed through the Model Context Protocol (MCP), which allows them to discover and invoke tools across multiple servers at runtime. Existing MCP benchmarks primarily measure task completion; where they diagnose failures, they do so after execution rather than building specific reasoning, execution, and memory failure risks into task construction. We introduce MCPHallu, a benchmark for diagnosing hallucination-prone agent failures in MCP environments along three axes: reasoning, execution, and memory. MCPHallu contains 358 tasks across five capability domains and runs on 36 production MCP servers in isolated containers. Each task is designed with a structural trigger that makes one of four subtypes the dominant failure risk: Branch Collapse, Unreachable Goal, Tool Misuse, or Context Forgetting. This design enables subtype-level analysis rathe"},{"url":"https://arxiv.org/abs/2611.07063","pdf":"https://arxiv.org/pdf/2611.07063.pdf","arxiv":"https://arxiv.org/abs/2611.07063","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"authors":["Mohammed Rahman Sherif Khan Mohammad","Ardhendu Behera","Sandip Pradhan","Swagat Kumar","Yonghuai Liu"],"tags":["VLM Training","Reasoning","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-04","id":"arxiv:2611.07063","title":"SD-LoRA: Training-Time Structural Distillation into LoRA for Few-Shot Vision-Language Adaptation","abstract":"Few-shot adaptation of vision-language models must balance two competing goals: learning fine-grained visual distinctions from very limited supervision and preserving the efficiency that makes frozen CLIP-like models attractive for deployment. Existing lightweight adaptation methods, including prompt tuning, LoRA, and cache-based adapters, typically supervise global image embeddings and therefore underuse token-level structure. Conversely, structure-aware methods exploit local evidence but often introduce additional inference-time computation. We propose SD-LoRA, a structural distillation framework that uses token-level graph reasoning only during training and transfers its effects into a lightweight LoRA-adapted CLIP model. During training, a heterogeneous graph teacher models patch-patch, global-local, and visual-text relations over high-resolution ViT tokens. Rather than retaining thi"},{"url":"https://arxiv.org/abs/2611.07639","pdf":"https://arxiv.org/pdf/2611.07639.pdf","arxiv":"https://arxiv.org/abs/2611.07639","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning","RL for LLM"],"authors":["Amit Sagtani","Saloni Garg"],"tags":["Post-Training","LLM Training","Evaluation","Fine-tuning","RL for LLM"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07639","title":"Measuring the Marginal Value of Verifier-Based RL Beyond Supervised Fine-Tuning","abstract":"Reinforcement learning from verifiable rewards (RLVR) is usually evaluated as an alternative to supervised fine-tuning (SFT), or as a stage that follows it, with the implicit assumption that the RL stage contributes gains of its own. We measure that contribution directly, in a controlled setting where both stages can be run to completion and compared exactly. We built gpu-train-debug, a deterministic benchmark of 1,877 synthetic GPU and LLM training failure diagnosis tasks across 30 archetypes, graded by a programmatic verifier with partial credit, and calibrated so that a mid-tier model scores in a 0.60 to 0.75 band. A pilot produced a surprise: 1,200 gold demonstrations nearly solved the benchmark (SFT 0.785 on the hard split), while 15 steps of GRPO from the base model did not move it (0.314 vs 0.311 base). We therefore amended the study, in writing and before the full run, to ask the"},{"url":"https://arxiv.org/abs/2611.07634","pdf":"https://arxiv.org/pdf/2611.07634.pdf","arxiv":"https://arxiv.org/abs/2611.07634","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","LLM Training","Planning","Evaluation","Fine-tuning"],"authors":["Siyuan Jiang","Xiang Cai","Peixu Wang","Yu Han","Yihong Dong","Wei Ning","Xuyuan Guo","Jincheng Wen","Dexin Liu","Wei Zhao","Ge Li"],"tags":["Post-Training","LLM Training","Planning","Evaluation","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07634","title":"AiXapply: Fast and Reliable Full-File Code Integration with Specialized Small Models for IDE Workflows","abstract":"Large language models increasingly assist developers by proposing small code edits, yet reliably integrating a partial update snippet into an existing file while preserving unrelated content remains poorly supported by current code-generation workflows. We formalize the Code Integration (Apply) task as follows: given an original file and an update snippet, the system must produce the complete merged file while preserving all content outside the requested edit. We construct a high-quality multi-language dataset from real commits via a structured pipeline that converts code changes into update snippets paired with full-file ground truth and enforces consistency through verification and filtering. We then train a specialized 4B model, aiXapply, using supervised fine-tuning and reinforcement learning (GRPO). The supervised variant achieves 94.4% accuracy under our language-aware comparison, "},{"url":"https://arxiv.org/abs/2611.08054","pdf":"https://arxiv.org/pdf/2611.08054.pdf","arxiv":"https://arxiv.org/abs/2611.08054","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Agentic RAG","Agentic Search","VLM Training","Fine-tuning"],"authors":["Lubnaa Abdur Rahman","Ioannis Papathanail","Maria Panagiotou","Nefeli Dimitropoulou","Margret Harðardóttir","Elisabeth J. den Brok","Bastiaan E. de Galan","Stavroula Georgia Mougiakakou"],"tags":["Agentic RAG","Agentic Search","VLM Training","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08054","title":"NutriVisRAG: Multimodal Exemplar Grounding for Nutrient Estimation with Vision-Language Models","abstract":"Diet is a major determinant of health, yet accurate dietary assessment from free-living meal images remains challenging. Existing retrieval-based Vision-Language Model (VLM) approaches to nutrient estimation typically rely on textual food representations, while, to our knowledge, direct grounding on visually similar annotated meals has not been investigated. We present NutriVisRAG, a retrieval-augmented generation framework that uses a vision encoder to retrieve similar meals with known nutritional annotations and provide them as multimodal in-context exemplars for VLM nutrient estimation at inference time, without task-specific fine-tuning. We evaluate NutriVisRAG across four datasets, four VLMs, three retrieval encoders, and two prompting strategies, including free-living meals from adults with insulin-treated diabetes, where carbohydrate estimates are compared against two dietitians' "},{"url":"https://arxiv.org/abs/2611.07482","pdf":"https://arxiv.org/pdf/2611.07482.pdf","arxiv":"https://arxiv.org/abs/2611.07482","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Reasoning","Evaluation","Alignment"],"authors":["Yichen Sun","Qirui Liu","Yan Wang","Jianan Lin","Linbo Jiang","Shiyu Wang","Zhibo Wang","Zhixuan Chu"],"tags":["LLM Training","Reasoning","Evaluation","Alignment"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07482","title":"SAVeR$^2$: Reasoning-based Safety Alignment for Large Reasoning Models via Verifiable Rewards","abstract":"Large Reasoning Models (LRMs) have achieved impressive performance via explicit Chain-of-Thought (CoT) reasoning, yet this process introduces critical safety risks. We formalize LRM safety objectives as requiring non-malicious reasoning and answers, safety consistency, and explicit intent identification. We argue that existing alignment methods suffer from poor adversarial generalization, a significant ``safety tax'' on reasoning, and unfaithful coarse-grained rewards, primarily due to their neglect of the LRM's intrinsic reasoning capabilities for safety. To address these, we propose \\textbf{SAVeR$^2$}, a novel \\textbf{S}afety \\textbf{A}lignment method via \\textbf{R}ewards with \\textbf{R}easoning capability. SAVeR$^2$ decomposes the safety objective into four fine-grained verifiable reward signals and utilizes a difficulty-aware data selection strategy to stabilize training. Crucially, "},{"url":"https://arxiv.org/abs/2611.07730","pdf":"https://arxiv.org/pdf/2611.07730.pdf","arxiv":"https://arxiv.org/abs/2611.07730","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Multi-Agent","Reasoning","Evaluation","World Model"],"authors":["Seong-Eun Hong","JuYeong Hwang","Jinhyun Kim","Hanyoung Jang","HyeongYeop Kang"],"tags":["Multi-Agent","Reasoning","Evaluation","World Model"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07730","title":"Seeing Beyond the Next Step: World-Model-Guided Human-Like Navigation in Multi-Agent Scenes","abstract":"Selecting a next motion in a populated scene is not just a matter of avoiding what is currently in the way: an action can be locally feasible yet drift onto the road instead of the crosswalk, cut into a stream of crossing pedestrians, or bottleneck a narrow passage. These failure modes are invisible from the current state alone, and acting on them requires reasoning about what each candidate action will cause. World models offer exactly this, namely action-conditioned predictions of the future, but rolling them out at every decision step is a cost deployable navigation systems cannot pay, and the field has largely traded foresight for speed. We argue this is a false dichotomy. The natural place for a world model in human-aware navigation is at training time, as a preference oracle that distills foresight into a fast policy, rather than at inference time, as an online planner. We pair a d"},{"url":"https://arxiv.org/abs/2611.08231","pdf":"https://arxiv.org/pdf/2611.08231.pdf","arxiv":"https://arxiv.org/abs/2611.08231","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Hallucination","Evaluation","Fine-tuning"],"authors":["Hanyu Qiu","Ze Liu","Zhe Zhao","Kuang Xiong","Blaze Chen","Zhenxiang Yan","Renfen Hu"],"tags":["LLM Training","Hallucination","Evaluation","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08231","title":"From Twisted Facts to Rogue Agents: Can LLMs Reliably Detect Multi-Dimensional Hallucinations?","abstract":"Large language models (LLMs) are widely used for information access, content production, and agent-based task execution, but their outputs remain vulnerable to subtle, high-risk hallucinations. To systematically evaluate and advance post-generation hallucination detection, we introduce HaluCheck, a large-scale, bilingual benchmark comprising over 42k instances spanning both factual hallucinations in text and faithfulness hallucinations in agent trajectories. HaluCheck features fine-grained, multi-level annotations for detection, localization, and correction, covering different tasks and perturbation degrees. Experiments on fourteen LLMs reveal that, while models show basic sample-level detection ability, they struggle with fine-grained localization, correction, and agent hallucination detection. Further analysis demonstrates that thinking, web search, and supervised fine-tuning each offe"},{"url":"https://arxiv.org/abs/2611.06956","pdf":"https://arxiv.org/pdf/2611.06956.pdf","arxiv":"https://arxiv.org/abs/2611.06956","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","Multi-Agent","RL for LLM","Agent Framework"],"authors":["Tianming Sha"],"tags":["Post-Training","Multi-Agent","RL for LLM","Agent Framework"],"upvotes":0,"submittedDate":"2026-11-03","id":"arxiv:2611.06956","title":"Octopus: One Brain, Many Branches for Latent-KV Multi-Agent Reinforcement Learning","abstract":"Multi-agent LLM systems explore in parallel by spawning sub-agents with isolated context windows, whereas single-agent systems append every search and verification step into one growing trajectory. However, existing multi-agent frameworks duplicate prefix KV caches across branches, exchange findings by re-prefilling text summaries, and flatten or drop cross-branch dependencies during reinforcement learning (RL). We introduce Octopus, a single-model multi-agent RL framework in which all threads share one backbone and coordinate over a GPU-resident directed acyclic graph (DAG) of KV states through five primitives (fork, read_thread, wait_threads, rewind, commit). Octopus combines three co-designed mechanisms: (1) Zero-Copy Radix Forking, which spawns branches as $\\mathcal{O}(1)$ cursor views over shared physical KV pages; (2) Attention-Only KV Mounting, which mounts a sibling thread's term"},{"url":"https://arxiv.org/abs/2611.07393","pdf":"https://arxiv.org/pdf/2611.07393.pdf","arxiv":"https://arxiv.org/abs/2611.07393","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation"],"authors":["Vihan Lakshman","Peter Baile Chen","Zhuohan Gu","Michael Cafarella"],"tags":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07393","title":"CacheGraft: Enhancing Retrieval-Augmented Generation via Latent-Space Document Enrichment","abstract":"Recent work in machine learning has demonstrated that transformer-based language model agents can communicate state not only through text, but also directly in latent space via key-value (KV) caches. In this paper, we argue that such cache-to-cache translation can provide utility beyond the original motivating application of real-time agent communication and can instead be utilized for retrieval-augmented generation (RAG). Building on the Cache-to-Cache (C2C) fusion framework, our proposed system CacheGraft encodes each corpus passage offline into a fused KV cache representation between a larger sharer model (4B parameters in our experiments) and a smaller receiver model (0.6B parameters) such that this cache can be injected into the receiver at query time with no need for the larger model. Across five QA benchmarks and two independent locally-run judges, CacheGraft improves answer quali"},{"url":"https://arxiv.org/abs/2611.08414","pdf":"https://arxiv.org/pdf/2611.08414.pdf","arxiv":"https://arxiv.org/abs/2611.08414","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Reasoning","Fine-tuning","RL for LLM"],"authors":["Chenruo Liu","Zihan Wang","Yijun Dong","Qi Lei"],"tags":["LLM Training","Reasoning","Fine-tuning","RL for LLM"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08414","title":"Spectral and Subspace Dynamics of LoRA in Supervised Fine-Tuning and Reinforcement Learning","abstract":"Low-rank adaptation (LoRA) is commonly used in both supervised fine-tuning (SFT) and reinforcement learning (RL), often under similar optimizer settings. Yet, how the different dynamics of the two stages manifest in the low-rank increment that LoRA optimizes remains unclear. Tracking the singular spectrum and subspaces of LoRA updates on mathematical reasoning tasks, we find that RL concentrates the spectrum at every learning rate, while SFT expands it at moderate learning rates; moreover, RL rotates the singular subspaces much faster than SFT at small learning rates. Interpolating between SFT and RL one ingredient at a time, we pinpoint group-mean baseline subtraction as the source of both contrasts. A quadratic multi-index model updated via LoRA unveils the underlying mechanism: group-mean baseline subtraction tilts the balance between two competing forces, coherent fitting and gradien"},{"url":"https://arxiv.org/abs/2611.07939","pdf":"https://arxiv.org/pdf/2611.07939.pdf","arxiv":"https://arxiv.org/abs/2611.07939","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","VLM Training","Evaluation","World Model"],"authors":["Jiahao Cui","Jiaye Li","Wenhao Zhang","Yaoyi Li","Shan Luan","Quanhui Tang","Jianhua Han","Lin Cheng","Hang Xu","Siyu Zhu"],"tags":["Post-Training","VLM Training","Evaluation","World Model"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07939","title":"WAM-Sim0.1: World Anchored Memory Meets Online RL for Consistent and Realistic Driving Simulation","abstract":"Autoregressive driving world models systematically suffer from structural drift, identity drift, and quality decay over long rollout horizons due to transient conditioning signals that lack persistent state. We present WAM-Sim, a driving world model anchored by a persistent hierarchical memory and optimized via online flow-matching RL. WAM-Sim structures persistent context across three temporal and semantic scales: pose-aligned structural tokens encoding persistent road topology, read-only scene tokens supplying geolocated background appearance, and write-once instance tokens preserving individual traffic participant identities across occlusions and chunk boundaries. To restore visual sharpness and physical plausibility degraded by multi-scale conditioning, we introduce an online post-training framework that optimizes self-generated rollouts via flow-matching RL guided by hierarchy-align"},{"url":"https://arxiv.org/abs/2608.11676","pdf":"https://arxiv.org/pdf/2608.11676.pdf","arxiv":"https://arxiv.org/abs/2608.11676","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Multi-Agent","Reasoning","Evaluation"],"authors":["Wooseong Yang","Wei-Chieh Huang","Weizhi Zhang","Yu Wang","Philip S. Yu","Junhyun Lee"],"tags":["Multi-Agent","Reasoning","Evaluation"],"upvotes":0,"submittedDate":"2026-09-28","id":"arxiv:2608.11676","title":"XBridge: Entity-Grounded Latent Bridge for Heterogeneous LLM Communication","abstract":"Heterogeneous multi-agent LLM systems, where agents are powered by different model families, can outperform homogeneous configurations by reducing redundant reasoning patterns. Yet existing communication protocols either operate through text, discarding the sender's internal representations, or require architectural homogeneity for latent-level transfer. We identify the entity grounding problem in cross-architecture communication: cross-attention bridges that transfer continuous representations across different LLM families suffer from rare-token compression collapse, where entity identity is lost in the continuous bottleneck (bridge-only F1 ~30%). We propose XBRIDGE, a decode-free communication protocol that addresses this through two mechanisms. Lexical Anchor Mapping (LAM) maps the sender's original context tokens to the receiver's vocabulary, providing discrete entity anchors. A Late"},{"url":"https://arxiv.org/abs/2611.08318","pdf":"https://arxiv.org/pdf/2611.08318.pdf","arxiv":"https://arxiv.org/abs/2611.08318","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Code Agent","Evaluation","Reflection"],"authors":["Wenbo Huang","Jianxin Bi","Shunyu Yang","Ruiyang Si","Rui Ni","Qiang Wang","Shulong Jiang","Yintianrun Zhang","Feixiang Ruan","Kewei Zhang","Ye Huang","Shukai Gong","Daquan Zhou"],"tags":["Code Agent","Evaluation","Reflection"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08318","title":"Learning the Task or Learning the Verifier? Rethinking Criteria Exposure in Embodied Self-Improvement","abstract":"Self-improving embodied agents are increasingly being developed and compared on robot simulation benchmarks. Several recent works expose the benchmark's success criteria to the learning agent, a practice we call Criteria Exposure (CE). These criteria, originally written to verify policies trained by imitation learning, often demand more than the corresponding language instructions, so a score from such a verifier may not faithfully reflect whether the instructed task was completed, especially for robot-control programs written by an agent. As embodied coding agents report ever higher benchmark scores, a natural question arises: when a coding agent is exposed to the benchmark's criteria, does it generate code that better performs the instructed task, or code that simply overfits to the verification criteria? We conduct controlled experiments with a self-improving agent with and without CE"},{"url":"https://arxiv.org/abs/2611.08082","pdf":"https://arxiv.org/pdf/2611.08082.pdf","arxiv":"https://arxiv.org/abs/2611.08082","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","Reasoning","Evaluation"],"authors":["Jinho Park","Se Young Chun","Mingoo Seok"],"tags":["Post-Training","Reasoning","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08082","title":"DictLLM: Post-training Compression of Large Language Model with Dictionary Kernels","abstract":"Efficient deployment of large language models (LLMs) on mobile devices requires balancing performance with compute and memory constraints. Post-training compression is an effective approach to managing this trade-off, while requiring much less computation than in-training counterparts. We propose DictLLM, a dictionary-based compression scheme in which weight matrices within grouped layers are decomposed into a shared dictionary and layer-specific sparse coefficients, directly obtained from a pre-trained model without further training. Specifically, we cast DictLLM as a four-step post-training optimization. First, we obtain shared dictionaries via singular value decomposition (SVD) of input-scaled weight matrices, amortizing rank across grouped layers; second, we sparsify the layer-specific coefficients to the target compression ratio using a dictionary-aware Hessian; and third, we refine"},{"url":"https://arxiv.org/abs/2611.07757","pdf":"https://arxiv.org/pdf/2611.07757.pdf","arxiv":"https://arxiv.org/abs/2611.07757","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Multi-Agent","Evaluation","Agent Framework"],"authors":["Yifan Chang","Yunze Li","Feifei Jiang","Juntao Wu","Xin Chen","Han Hu","Yucheng Wu","Wei Tang","Mingqian Ma","Wanli Ouyang","Kaipeng Zhang","Lei Bai","Hongting Tang","Feiran Li","Yuchen Ren"],"tags":["Multi-Agent","Evaluation","Agent Framework"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07757","title":"RIVER: Evidence-guided multi-agent retrieval for enzyme--reaction discovery","abstract":"Enzyme function annotation and the identification of candidate enzymes for a given reaction are essential steps in connecting genomic information to biochemical reaction networks. However, existing methods rely on sequence or structural similarity or on training with known enzyme--reaction pairs, making it difficult to integrate biochemical evidence across large candidate spaces; they also struggle with retrieval tasks involving enzyme families whose members are highly similar. Here, we introduce RIVER (Reaction--enzyme Inference via Evidence-guided Retrieval), a multi-agent framework for bidirectional enzyme--reaction retrieval that identifies potentially catalyzed reactions for a given enzyme and ranks candidate enzymes for a given reaction. RIVER coordinates large language models, specialized biochemical computational tools, and external knowledge resources to assemble evidence at mul"},{"url":"https://arxiv.org/abs/2611.07717","pdf":"https://arxiv.org/pdf/2611.07717.pdf","arxiv":"https://arxiv.org/abs/2611.07717","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Yu Cao","Haiyan Xu","Xiaohan Li","Jian Yang","Yuqing Feng","Wei Wang","Haomin Li"],"tags":["LLM Training","Evaluation","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07717","title":"Pediatric ECG foundation model via adult-to-pediatric fine-tuning: downstream tasks and clinical evaluation","abstract":"Pediatric electrocardiogram (ECG) interpretation is complicated by age-dependent electrophysiological changes that limit direct transfer of adult AI models. We asked whether an adult ECG foundation model could be adapted to pediatric ECGs. Using 339,563 12-lead ECGs from 238,189 children, we compared direct application, pediatric fine-tuning, and training from scratch under an identical architecture. Direct transfer was poor (mean AUC 0.8256). Fine-tuning reached 0.9695, above de novo training (0.9661), and attained 0.9079 using only 1% of training data. On 10,999 external ECGs, fine-tuning achieved a mean AUC of 0.9385 across 30 labels. It generalized to age regression (MAE 1.12 years) and congenital heart disease classification (AUC 0.9562). Across 17 clinicians and 100 cases, diagnostic accuracy rose from 56.8% to 65.4% (p < 0.001) and did not decline when AI erred. Adult ECG foundati"},{"url":"https://arxiv.org/abs/2611.08196","pdf":"https://arxiv.org/pdf/2611.08196.pdf","arxiv":"https://arxiv.org/abs/2611.08196","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Multi-Agent","Reasoning","Agent Framework"],"authors":["Sai Vallurupalli","Francis Ferraro"],"tags":["Multi-Agent","Reasoning","Agent Framework"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08196","title":"SMART: State-based Multi Agent Reasoning Traces for Verification-oriented Problem-Solving","abstract":"Complex problems with limited context, such as claims, require a means to obtain additional knowledge necessary for solution reasoning. We propose a multi-agent framework, SMART, to obtain knowledge through capturing the implicit state of participating entities in a problem context. SMART curates the state knowledge as diverse, complementary and solution-salient premises using a variety of LLMs and a structured role-based prompt strategy. Using knowledge from these real-world verified curated premises, SMART's knowledge guided solution reasoning improves validation performance up to 20% on complex scientific claims spanning 3 datasets. We show that grounding premises in real-world knowledge is necessary and improves performance up to 5%."},{"url":"https://arxiv.org/abs/2611.08315","pdf":"https://arxiv.org/pdf/2611.08315.pdf","arxiv":"https://arxiv.org/abs/2611.08315","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Reasoning","Hallucination","Evaluation"],"authors":["Ali Sarabadani","Kheirolah Rahsepar Fard","Tahereh Jeirani"],"tags":["Reasoning","Hallucination","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.08315","title":"Benchmarking Large Language Models on Heterogeneous Cognitive and Biomedical Knowledge Graphs: The Role of Graph Grounding in Multi-Hop Reasoning and Hallucination Mitigation","abstract":"Large language models (LLMs) are increasingly used in biomedical and cognitive neuroscience, but their ability to reason reliably over heterogeneous knowledge graphs (KGs) remains unclear. We benchmark five LLMs (GPT-5.1, Gemini 2.0 Pro, Llama 3, Qwen, and BioGPT) across five KGs: DrugBank, NeuroSynth, Cognitive Atlas, Brain Map, and GDPKG. We introduce a multitier query dataset to evaluate reasoning depth and factual accuracy under KG-aware (graph-grounded) and KG-agnostic conditions. Inter-annotator agreement was substantial, with Cohen's kappa of 0.781 (range: 0.753-0.807) and Fleiss' kappa of 0.77. Results show that general-purpose models, particularly GPT-5.1 and Gemini 2.0 Pro, generally outperform domain-specific models on multi-hop and high-level reasoning tasks, although performance declines as query complexity increases. KG grounding reduces hallucination rates across all evalu"},{"url":"https://arxiv.org/abs/2611.07541","pdf":"https://arxiv.org/pdf/2611.07541.pdf","arxiv":"https://arxiv.org/abs/2611.07541","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Post-Training","Reasoning","Evaluation"],"authors":["Ying Li","Yongle Cheng","Jing Li","Xingquan Cai","Yawei Luo"],"tags":["Post-Training","Reasoning","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07541","title":"CST-Bench: Benchmarking Counterfactual Spatial Transition Reasoning with Causal Transition On-Policy Self-Distillation","abstract":"Spatial reasoning is a fundamental capability of multimodal large language models (MLLMs), yet existing benchmarks mainly focus on static scene understanding. When objects are moved or swapped, models must infer not only spatial relations but also how interventions change the scene state. To address this problem, we introduce CST-Bench, a benchmark for counterfactual spatial reasoning. CST-Bench contains 7,082 examples covering 6 intervention types and 12 transformation operators, with dense causal annotations including intervention sources, affected relations, expected effects, invariant relations, and metric changes. We benchmark general-purpose MLLMs on CST-Bench and further compare post-training strategies on CST-Bench and standard spatial benchmarks. Results show that methods effective for ordinary spatial reasoning can still fail under counterfactual interventions. We further formu"},{"url":"https://arxiv.org/abs/2611.07640","pdf":"https://arxiv.org/pdf/2611.07640.pdf","arxiv":"https://arxiv.org/abs/2611.07640","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Agent Safety","Tool Use","Evaluation"],"authors":["Rongting Zhang","Martin Bertran","Sandeep Avula","Chia-Jung Lee","Vanessa Murdock"],"tags":["Agent Safety","Tool Use","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07640","title":"Beyond Instruction Override: Benchmarking Indirect Prompt Injection with Task-Tampering Attacks","abstract":"Indirect prompt-injection (IPI) benchmarks predominantly test planted instructions that redirect a tool-using agent toward an attacker-chosen task. Yet attacker-controlled content can instead tamper with the outcome of the task already in progress. A buyer's dispute evidence can cite a false refund policy to inflate a refund without changing the task. We define IPI by authority rather than instruction-like wording: planted content constitutes an attack when it attempts to influence a decision that its source is not authorized to determine. We introduce a benchmark that makes this boundary explicit: in each of 90 validated cases across three tool-use environments, the user request specifies the source that resolves the targeted decision. Every attack tampers with a decision required by the benign task rather than replacing that task. Each case has attacks with the same harmful outcome tha"},{"url":"https://arxiv.org/abs/2611.07513","pdf":"https://arxiv.org/pdf/2611.07513.pdf","arxiv":"https://arxiv.org/abs/2611.07513","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","VLM Training","Evaluation"],"authors":["Chengcheng Wang","Wei He","Wenhao Li","Hongguang Li","Kai Han","Jianyuan Guo","Chang Xu"],"tags":["LLM Training","VLM Training","Evaluation"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07513","title":"Concertina: Embodying Manipulation and Cognition in One Diffusion Vision-Language Model","abstract":"Most vision-language-action (VLA) policies decouple manipulation from cognition by bolting an external action mechanism onto a vision-language model (VLM)--either quantizing actions into discrete tokens whose errors bear no stable correspondence to physical displacements, or delegating continuous trajectory generation to a separate action expert whose gradients compete with or are blocked from updating the VLM backbone. We argue that manipulation and cognition should instead be embodied in the same model, shifting from a decoupled VLA to an Embodied Vision-Language Model (eVLM). We introduce Concertina, an eVLM that places continuous trajectory representation, blockwise generation, and physical-coordinate supervision directly on the computation and parameter path of a shared diffusion VLM backbone. Each control timestep is encoded as one continuous latent action token in the backbone hid"},{"url":"https://arxiv.org/abs/2611.06988","pdf":"https://arxiv.org/pdf/2611.06988.pdf","arxiv":"https://arxiv.org/abs/2611.06988","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Rishit Jain","Rishit Kar","Chetashri Bhadane","Nilesh Patil"],"tags":["LLM Training","Evaluation","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-04","id":"arxiv:2611.06988","title":"Big Models, Small Gains: Frozen Forecasters as Classifiers on MONSTER","abstract":"Forecasting foundation models are increasingly used as frozen feature extractors for time series classification, but it remains unclear whether their pretrained representations offer an advantage over strong classifiers that do not require pretraining. This raises an important question: do these representations provide useful information beyond what the model architecture alone can capture, particularly when labelled data are scarce? We present a controlled benchmarking of two forecasting models, Reverso and Chronos-Bolt, on six large datasets from the MONSTER benchmark, using 1%, 10%, and 100% of the available training labels. We compare their frozen representations against four established time series classification methods and random-weight versions of the same forecasting models. Our results show that pretraining improves classification accuracy over random-weight counterparts on fiv"},{"url":"https://arxiv.org/abs/2611.07140","pdf":"https://arxiv.org/pdf/2611.07140.pdf","arxiv":"https://arxiv.org/abs/2611.07140","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["Error Attribution","Multi-Agent","Evaluation"],"authors":["Burkay Tunçtürk","Koorosh Aslansefat","Yiannis Papadopoulos","Bao Nguyen"],"tags":["Error Attribution","Multi-Agent","Evaluation"],"upvotes":0,"submittedDate":"2026-11-04","id":"arxiv:2611.07140","title":"More Agents, More Reliable? System-Level Reliability of Multi-Agent LLMs under Operational-Profile Uncertainty","abstract":"Teams increasingly build software from cooperating large language model (LLM) agents, often assuming more agents mean more reliability. Yet the usual evidence, average benchmark accuracy, ignores the input mix a deployed system meets and the rule merging the agents' answers. Building on HIP-LLM, a hierarchical imprecise-probability assessment of single LLMs, we propose a framework combining it with a Bayesian network of the system's failure logic for multi-agent systems. Agent failure-probability intervals propagate through this network, where the combining rule can itself fail, into a reliability envelope showing which evidence limits it. In a pipeline extracting regulated chemical-hazard statements, majority voting over three models protected against the weakest but did not clearly exceed the best, and a voter failing on 5\\% of demands would largely erase its advantage over the middle "},{"url":"https://arxiv.org/abs/2611.07940","pdf":"https://arxiv.org/pdf/2611.07940.pdf","arxiv":"https://arxiv.org/abs/2611.07940","date":"2026-11-06","source":"arxiv","announceDate":"2026-11-06","topics":["LLM Training","Evaluation","Fine-tuning"],"authors":["Manuela-Daniela Danu","Miguel Rodríguez-Ortega","Alberto Becerra-Tome","Pablo Arancibia","Fernando Gallego-Donoso","Lorenzo Pratesi","Xi Bai","Andrei-Damian Dinescu","Salvador Lima-López","Andrea Guala","Saskia Haitjema","Jonas Mack","Michele Miranda","Wesam Al Nabki","Jan Rodríguez-Miret","Vasile George Marica","Vladimír Kincl","Kateřina Dostálová","Michael Andrej","Alicia Ujil","Corinne Allaart","Machteld Boonstra","Malin Overmars","Anoop Shah","Giovanna Ceroni","Jonathan Kossoff","Domenico D'Amario","Renzo Laborante","Antonio Iaconelli","Isabella Fumarulo","Jacopo Lenkowicz","Livia Lilli","Emma Weiss","Alex Scafa","Felix Lindberg","Milou Gamage","Eulàlia Farré-Maduell","Sébastien Bratières","Martin Krallinger","Bram van Es"],"tags":["LLM Training","Evaluation","Fine-tuning"],"upvotes":0,"submittedDate":"2026-11-05","id":"arxiv:2611.07940","title":"CardioLM: A multilingual suite of small language models for the cardiology domain","abstract":"Background: Cardiovascular care generates large volumes of clinical free-text documentation in local languages. However, clinical natural language processing (NLP) resources remain concentrated in English, and no existing benchmark is cardiology-specific, multilingual, and broad in entity coverage. Methods: We present two contributions. The first is CardioCCC, a corpus of 508 cardiology case reports originally published in Spanish and extended to Czech, Dutch, English, Italian, Romanian, and Swedish through machine translation, annotation projection, and clinician review, with annotations covering diseases, symptoms, procedures, and medications. The second is CardioLM, comprising CardioBERTa, a set of language-specific encoders obtained by continued pretraining on cardiology and biomedical corpora, and CardioNER, a set of named entity recognition (NER) models fine-tuned on CardioCCC. Res"}],"archive":[],"latestPath":"data/latest.json"};
